<?php ?><!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conditioneri — Панель управления</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="admin-style.css"></head><body><div class="admin-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">C</span><div><b>Conditioneri</b><small>Панель управления</small></div></div><nav><button class="nav-item active" data-section="dashboard">⌂ Обзор</button><button class="nav-item" data-section="orders">◷ Заказы <em id="new-count">0</em></button><button class="nav-item" data-section="catalog">▦ Каталог</button><button class="nav-item" data-section="services">⚙ Услуги</button><button class="nav-item" data-section="reviews">★ Отзывы</button><button class="nav-item" data-section="portfolio">▧ Примеры работ</button></nav><div class="sidebar-bottom"><a href="index.html" target="_blank">↗ Открыть сайт</a></div></aside><main class="content"><header class="topbar"><div><div class="eyebrow">Управление сайтом</div><h1 id="page-title">Обзор</h1></div><button class="refresh" id="refresh">↻ Обновить</button></header><section id="dashboard" class="section active-section"><div class="stats"><article><span>Всего заказов</span><strong id="stat-orders">—</strong></article><article><span>Новые</span><strong id="stat-new">—</strong></article><article><span>В работе</span><strong id="stat-work">—</strong></article><article><span>Позиций каталога</span><strong id="stat-products">—</strong></article></div><div class="card"><div class="card-head"><h2>Последние заявки</h2></div><div id="dashboard-orders" class="table-wrap"></div></div></section><section id="orders" class="section"><div class="section-head"><div><h2>Заказы</h2><p>Полная карточка заказа: клиент, позиции, количество, цены, сумма и статус.</p></div></div><div class="toolbar"><input id="order-search" class="search" placeholder="⌕ Поиск по имени или телефону"><select id="status-filter"><option value="all">Все статусы</option><option value="new">Новые</option><option value="contacted">Связались</option><option value="confirmed">Подтверждены</option><option value="completed">Завершены</option><option value="cancelled">Отменены</option></select></div><div class="card table-wrap" id="orders-table"></div></section><section id="catalog" class="section"><div class="section-head"><div><h2>Каталог</h2><p>Кондиционеры и сплит-системы.</p></div><button class="primary" id="add-product">＋ Добавить товар</button></div><div id="catalog-grid" class="catalog-grid"></div></section><section id="services" class="section"><div class="section-head"><div><h2>Услуги</h2><p>Этот раздел отображается сразу под каталогом на сайте.</p></div><button class="primary" id="add-service">＋ Добавить услугу</button></div><div id="services-grid" class="catalog-grid"></div></section><section id="reviews" class="section"><div class="section-head"><div><h2>Отзывы</h2><p>Отзывы клиентов для публикации на сайте.</p></div><button class="primary" id="add-review">＋ Добавить отзыв</button></div><div id="reviews-grid" class="catalog-grid"></div></section><section id="portfolio" class="section"><div class="section-head"><div><h2>Примеры работ</h2><p>Фотографии установок с описанием выполненной работы.</p></div><button class="primary" id="add-work">＋ Добавить работу</button></div><div id="portfolio-grid" class="catalog-grid"></div></section></main></div><div id="modal" class="modal hidden"><div class="modal-box"><div class="modal-head"><div><h2 id="modal-title">Новая запись</h2></div><button class="close" id="close-modal">×</button></div><form id="content-form" enctype="multipart/form-data"></form></div></div><div id="toast" class="toast"></div><script>
const state={orders:[],products:[],services:[],reviews:[],portfolio:[]},labels={new:'Новый',contacted:'Связались',confirmed:'Подтверждён',completed:'Завершён',cancelled:'Отменён'},$=s=>document.querySelector(s),money=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(v))+' ₽';
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function toast(m,e=false){const t=$('#toast');t.textContent=m;t.className='toast show '+(e?'error':'');setTimeout(()=>t.className='toast',2500)}async function api(u,o={}){const r=await fetch(u,o),d=await r.json();if(!r.ok||d.status==='error')throw Error(d.message||d.error||'Ошибка');return d}
async function load(){try{[state.orders,state.products,state.services,state.reviews,state.portfolio]=await Promise.all([api('orders.php'),api('catalog.php'),api('content.php?type=services'),api('content.php?type=reviews'),api('content.php?type=portfolio')]);render()}catch(e){toast(e.message,true)}}
function orderRows(list,limit=0){let a=limit?list.slice(0,limit):list;if(!a.length)return '<div class="empty">Заказов пока нет</div>';return `<table><thead><tr><th>ID</th><th>Клиент</th><th>Телефон</th><th>Позиции</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>${a.map(o=>`<tr class="order-row" data-order="${o.id}" title="Открыть карточку заказа"><td><button class="order-open text-btn" data-id="${o.id}">#${o.id}</button></td><td><button class="order-open text-btn" data-id="${o.id}"><b>${esc(o.name)}</b></button></td><td><a href="tel:${esc(o.phone)}">${esc(o.phone)}</a></td><td>${o.items?.length?`${o.item_count} поз. <span class="muted">· ${o.items.slice(0,2).map(i=>esc(i.title)).join(', ')}${o.items.length>2?'…':''}</span>`:'<span class="muted">Нет позиций</span>'}</td><td><b>${money(o.total||0)}</b></td><td><select class="status-select ${o.status}" data-id="${o.id}">${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${o.status===v?'selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`}
function renderOrders(){let q=$('#order-search')?.value.toLowerCase()||'',f=$('#status-filter')?.value||'all';let a=state.orders.filter(o=>(f==='all'||o.status===f)&&(`${o.name} ${o.phone}`.toLowerCase().includes(q)));$('#orders-table').innerHTML=orderRows(a);$('#dashboard-orders').innerHTML=orderRows(state.orders,5);document.querySelectorAll('.status-select').forEach(x=>x.onchange=changeStatus);document.querySelectorAll('.order-open').forEach(x=>x.onclick=()=>openOrder(+x.dataset.id))}
function renderCatalog(){const g=$('#catalog-grid');g.innerHTML=state.products.length?state.products.map(p=>`<article class="product"><div class="product-image">${p.image?`<img src="${esc(p.image)}">`:'Нет фото'}</div><div class="product-body"><h3>${esc(p.name)}</h3><p>${esc(p.description||'Описание не задано')}</p><strong>${money(p.price)}</strong><div class="product-actions"><button class="secondary" onclick="openProduct(${p.id})">Изменить</button><button class="danger" onclick="deleteEntity('catalog.php?id=${p.id}','Товар')">Удалить</button></div></div></article>`).join(''):'<div class="empty card">Каталог пуст.</div>'}
function cards(type){let g=$('#'+type+'-grid'),a=state[type];if(!a.length){g.innerHTML='<div class="empty card">Пока нет записей.</div>';return}g.innerHTML=a.map(x=>type==='services'?`<article class="product"><div class="product-body"><h3>${esc(x.name)}</h3><p>${esc(x.description||'')}</p><strong>${esc(x.price||'По договорённости')}</strong><div class="product-actions"><button class="secondary" onclick="openService(${x.id})">Изменить</button><button class="danger" onclick="deleteEntity('content.php?type=services&id=${x.id}','Услугу')">Удалить</button></div></div></article>`:type==='reviews'?`<article class="product"><div class="product-body"><h3>${esc(x.name)} · ${'★'.repeat(Math.min(5,Math.max(1,Number(x.rating)||1)))}</h3><p>${esc(x.text)}</p><div class="product-actions"><button class="secondary" onclick="openReview(${x.id})">Изменить</button><button class="danger" onclick="deleteEntity('content.php?type=reviews&id=${x.id}','Отзыв')">Удалить</button></div></div></article>`:`<article class="product"><div class="product-image"><img src="${esc(x.image)}" loading="lazy"></div><div class="product-body"><h3>${esc(x.title)}</h3><p>${esc(x.description||'')}</p><div class="product-actions"><button class="secondary" onclick="openWork(${x.id})">Изменить</button><button class="danger" onclick="deleteEntity('content.php?type=portfolio&id=${x.id}','Работу')">Удалить</button></div></div></article>`).join('')}
function render(){let n=state.orders.filter(o=>o.status==='new').length,w=state.orders.filter(o=>['contacted','confirmed'].includes(o.status)).length;$('#stat-orders').textContent=state.orders.length;$('#stat-new').textContent=n;$('#stat-work').textContent=w;$('#stat-products').textContent=state.products.length;$('#new-count').textContent=n;renderOrders();renderCatalog();cards('services');cards('reviews');cards('portfolio')}
async function changeStatus(e){try{await api('orders.php',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:e.target.dataset.id,status:e.target.value})});await load();toast('Статус обновлён')}catch(x){toast(x.message,true)}}
function form(fields,title,handler){$('#modal-title').textContent=title;$('#content-form').innerHTML=fields+'<div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div>';$('#content-form').onsubmit=handler;$('#modal').classList.remove('hidden')}
function openProduct(id){let p=state.products.find(x=>x.id===id)||{};form(`<input type="hidden" name="id" value="${p.id||''}"><label>Название<input required name="name" value="${esc(p.name||'')}"></label><label>Цена<input required type="number" min="0" step="0.01" name="price" value="${p.price||''}"></label><label>Описание<textarea name="description">${esc(p.description||'')}</textarea></label><label>Фото<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label>`,`${p.id?'Редактировать товар':'Новый товар'}`,async e=>saveForm(e,'catalog.php'))}
function openService(id){let x=state.services.find(v=>v.id===id)||{};form(`<input type="hidden" name="id" value="${x.id||''}"><label>Название<input required name="name" value="${esc(x.name||'')}"></label><label>Описание<textarea name="description">${esc(x.description||'')}</textarea></label><label>Цена / условие<input name="price" value="${esc(x.price||'')}"></label>`,'Услуга',async e=>saveForm(e,'content.php?type=services'))}
function openReview(id){let x=state.reviews.find(v=>v.id===id)||{};form(`<input type="hidden" name="id" value="${x.id||''}"><label>Имя клиента<input required name="name" value="${esc(x.name||'')}"></label><label>Оценка<select name="rating">${[5,4,3,2,1].map(n=>`<option ${x.rating==n?'selected':''}>${n}</option>`)}</select></label><label>Отзыв<textarea required name="text">${esc(x.text||'')}</textarea></label>`,'Отзыв',async e=>saveForm(e,'content.php?type=reviews'))}
function openWork(id){let x=state.portfolio.find(v=>v.id===id)||{};form(`<input type="hidden" name="id" value="${x.id||''}"><label>Название работы<input required name="title" value="${esc(x.title||'')}"></label><label>Описание<textarea name="description">${esc(x.description||'')}</textarea></label><label>Фото<input ${x.id?'':'required'} type="file" name="image" accept="image/jpeg,image/png,image/webp"></label>`,'Пример работы',async e=>saveForm(e,'content.php?type=portfolio'))}
async function saveForm(e,url){e.preventDefault();try{await api(url,{method:'POST',body:new FormData(e.target)});closeModal();await load();toast('Сохранено')}catch(x){toast(x.message,true)}}async function deleteEntity(url,name){if(!confirm(`Удалить ${name}?`))return;try{await api(url,{method:'DELETE'});await load();toast('Удалено')}catch(x){toast(x.message,true)}}
async function addItem(order){let opts=state.products.map(p=>`<option value="p:${p.id}">${esc(p.name)} — ${money(p.price)}</option>`).join('')+state.services.map(s=>`<option value="s:${s.id}">${esc(s.name)} — ${esc(s.price||'по договорённости')}</option>`).join('');if(!opts){toast('Сначала добавьте товар или услугу',true);return}form(`<input type="hidden" name="order_id" value="${order}"><label>Позиция<select name="item">${opts}</select></label><label>Количество<input type="number" name="quantity" min="1" max="99" value="1"></label>`,'Добавить позицию',async e=>{e.preventDefault();let fd=new FormData(e.target),[kind,id]=fd.get('item').split(':');let body={order_id:order,quantity:fd.get('quantity')};body[kind==='p'?'product_id':'service_id']=id;try{await api('order-items.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});closeModal();await load();toast('Позиция добавлена');openOrder(order)}catch(x){toast(x.message,true)}})}
function closeModal(){$('#modal').classList.add('hidden')}function showSection(id){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active-section'));$('#'+id).classList.add('active-section');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.section===id));$('#page-title').textContent={dashboard:'Обзор',orders:'Заказы',catalog:'Каталог',services:'Услуги',reviews:'Отзывы',portfolio:'Примеры работ'}[id]}
document.querySelectorAll('.nav-item').forEach(x=>x.onclick=()=>showSection(x.dataset.section));$('#refresh').onclick=load;$('#order-search').oninput=renderOrders;$('#status-filter').onchange=renderOrders;$('#add-product').onclick=()=>openProduct();$('#add-service').onclick=()=>openService();$('#add-review').onclick=()=>openReview();$('#add-work').onclick=()=>openWork();$('#close-modal').onclick=closeModal;load();</script><script src="admin-orders.js"></script></body></html>